INSERT INTO system.company_setting (id, singleton, company_name_en, company_name_ar, cr_number, vat_id, vat_enabled, vat_percentage, vat_certificate_url, default_currency, currency_decimals, address_en, address_ar, phone, country_code, mobile_number, whatsapp_phone, whatsapp_country_code, whatsapp_mobile_number, email, website, instagram_url, linkedin_url, youtube_url, map_url, bank_name, bank_iban, bank_account_number, bank_swift, time_zone, logo_url, dark_logo_url, full_logo_url, dark_full_logo_url, icon_url, dark_icon_url, stamp_url, signature_url, document_header_url, document_footer_url, payment_terms_days, invoice_prefix, invoice_next_number, receipt_prefix, receipt_next_number, ceo_name_en, ceo_name_ar, ceo_title_en, ceo_title_ar, ceo_quote_en, ceo_quote_ar, tagline_en, tagline_ar, about_text_en, about_text_ar, mission_en, mission_ar, vision_en, vision_ar, terms_en, terms_ar, rules_en, rules_ar, founded_year, city, country, primary_language, business_activity, default_discount_limit_percent, quotations_always_need_approval, theme, setup_completed_at, website_domain, admin_domain, updated_at) VALUES ('c0000000-0000-0000-0000-000000000001', 1, 'Al-Hayat Pharmacy & Wellness W.L.L.', 'صيدلية الحياة والعافية ذ.م.م', 'CR-131770-1', '200013177000002', true, 10, '/api/files/brand/stamp.png', 'BHD', 3, 'Shop 4, Dana Mall Medical Arcade, Sanabis', 'محل 4، رواق الدانة الطبي، السنابس', '+97317558800', 'BH', '17558800', '+97339558800', 'BH', '39558800', 'care@alhayatpharmacy.bh', 'https://alhayatpharmacy.bh', 'https://instagram.com/hayat-pharmacy', 'https://linkedin.com/company/hayat-pharmacy', 'https://youtube.com/@hayat-pharmacy', 'https://maps.google.com/?q=Sanabis%2C%20Bahrain', 'National Bank of Bahrain (NBB)', 'BH39NBOB00000031770001', '0031770001', 'NBOBBHBM', 'Asia/Bahrain', '/api/files/brand/logo-dark.png', '/api/files/brand/logo-light.png', '/api/files/brand/logo-dark.png', '/api/files/brand/logo-light.png', '/api/files/brand/icon-light.png', '/api/files/brand/icon-dark.png', '/api/files/brand/stamp.png', '/api/files/brand/signature.png', '/api/files/media/banners/banner-01.png', '/api/files/media/banners/banner-02.png', 30, 'HYP', 150, 'RCT', 150, 'Dr. Zainab Al-Saffar', 'د. زينب الصفار', 'Chief Pharmacist & Managing Director', 'كبيرة الصيادلة والمديرة العامة', 'Precision delivery from Sanabis across the GCC.', 'التميز التشغيلي من Sanabis إلى جميع أسواق الخليج.', 'Clinical Pharmacy, Vitamins & Express Wellness Delivery', 'صيدلية سريرية وفيتامينات وتوصيل سريع للعافية', 'NHRA-licensed community pharmacy network offering prescription care, clinical dermocosmetics, and 60-minute express delivery.', 'شبكة صيدليات مرخصة تقدم الرعاية الدوائية ومستحضرات العناية الطبية والتوصيل السريع.', 'Deliver benchmark pharmacy services with clear bilingual accountability.', 'تقديم خدمات موثوقة ثنائية اللغة وفق أعلى معايير الجودة والالتزام.', 'To lead Bahrain''s enterprise ecosystem in pharmacy innovation.', 'أن نكون الشريك المرجعي الأول لقطاع الأعمال في مملكة البحرين والخليج.', 'Invoices are payable within 30 calendar days in BHD. Late balances accrue documented reminders.', 'تستحق الفواتير خلال 30 يوماً بعملة BHD وفق شروط العقد المعتمد.', '10% VAT compliant with Bahrain NBR e-invoicing guidelines; signed approvals logged digitally.', 'تطبق ضريبة القيمة المضافة 10% وفق متطلبات الجهاز الوطني للإيرادات.', 2016, 'Sanabis', 'BH', 'ar', 'pharmacy', 15, false, '{"primary":"#047857","accent":"#0EA5E9","radius":"md","defaultMode":"light","fonts":{"body":{"kind":"google","family":"IBM Plex Sans Arabic"},"heading":{"kind":"google","family":"IBM Plex Sans Arabic"}}}'::jsonb, '2026-01-01T00:00:00Z', 'alhayatpharmacy.bh', 'admin.alhayatpharmacy.bh', now()) ON CONFLICT (id) DO NOTHING;
