INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-1', 'pcat-cms-1', 'hayat-pharmacy-case-1', 'NHRA Cold-Chain Biologics Excellence Award', 'جائزة التميز في سلاسل التبريد الدوائية NHRA', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered for Al-Jazeera Gulf Holdings W.L.L. across Sanabis with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة الجزيرة الخليجية القابضة في Sanabis وفق أعلى معايير الجودة والالتزام.', 20, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://alhayatpharmacy.bh/work/hayat-pharmacy-case-1', 'Sanabis, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'hayat-pharmacy-2026-outlook', 'Al-Hayat Pharmacy 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — صيدلية الحياة', 'Key operational benchmarks, real metrics, and 2026 guidance from Al-Hayat Pharmacy in Sanabis.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من صيدلية الحياة في Sanabis.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"NHRA-licensed community pharmacy network offering prescription care, clinical dermocosmetics, and 60-minute express delivery. Focusing on Pharmacist Medication Review, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شبكة صيدليات مرخصة تقدم الرعاية الدوائية ومستحضرات العناية الطبية والتوصيل السريع. من خلال خدمة مراجعة دوائية مع الصيدلي نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>NHRA-licensed community pharmacy network offering prescription care, clinical dermocosmetics, and 60-minute express delivery.</p><p>Focusing on <strong>Pharmacist Medication Review</strong>, our Sanabis specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شبكة صيدليات مرخصة تقدم الرعاية الدوائية ومستحضرات العناية الطبية والتوصيل السريع.</p><p>من خلال خدمة <strong>مراجعة دوائية مع الصيدلي</strong>، يعمل فريقنا في Sanabis على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Al-Hayat Pharmacy 2026 GCC Market Outlook & Benchmarks | Al-Hayat Pharmacy', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — صيدلية الحياة | صيدلية الحياة', 'Executive guide by Al-Hayat Pharmacy covering Pharmacist Medication Review benchmarks in Bahrain.', 'دليل تنفيذي من صيدلية الحياة حول معايير مراجعة دوائية مع الصيدلي في البحرين.', 'Insights', '{"pharmacy","insights","Sanabis","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Al-Hayat Pharmacy initiate a Pharmacist Medication Review engagement?', 'كم يستغرق بدء تنفيذ خدمة مراجعة دوائية مع الصيدلي لدى صيدلية الحياة؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Sanabis.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Sanabis.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-2', 'pcat-cms-2', 'hayat-pharmacy-case-2', '6-Branch Synchronized Chronic Refill App', 'ربط صرف الأدوية المزمنة عبر 6 فروع رقمياً', 'Bahrain Bay Hospitality Group', 2026, 'Delivered for Bahrain Bay Hospitality Group across Sanabis with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة خليج البحرين للضيافة في Sanabis وفق أعلى معايير الجودة والالتزام.', 6, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://alhayatpharmacy.bh/work/hayat-pharmacy-case-2', 'Sanabis, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-2', 'hayat-pharmacy-service-standards', 'Inside Our Clinical SLA: Speed, Quality & Auditability', 'معايير اتفاقية مستوى الخدمة والجودة في مراجعة دوائية مع الصيدلي', 'Key operational benchmarks, real metrics, and 2026 guidance from Al-Hayat Pharmacy in Sanabis.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من صيدلية الحياة في Sanabis.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"NHRA-licensed community pharmacy network offering prescription care, clinical dermocosmetics, and 60-minute express delivery. Focusing on 24/7 Prescription Verification & Delivery, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شبكة صيدليات مرخصة تقدم الرعاية الدوائية ومستحضرات العناية الطبية والتوصيل السريع. من خلال خدمة صرف الوصفات الطبية والتوصيل على مدار الساعة نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>NHRA-licensed community pharmacy network offering prescription care, clinical dermocosmetics, and 60-minute express delivery.</p><p>Focusing on <strong>24/7 Prescription Verification & Delivery</strong>, our Sanabis specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شبكة صيدليات مرخصة تقدم الرعاية الدوائية ومستحضرات العناية الطبية والتوصيل السريع.</p><p>من خلال خدمة <strong>صرف الوصفات الطبية والتوصيل على مدار الساعة</strong>، يعمل فريقنا في Sanabis على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Inside Our Clinical SLA: Speed, Quality & Auditability | Al-Hayat Pharmacy', 'معايير اتفاقية مستوى الخدمة والجودة في مراجعة دوائية مع الصيدلي | صيدلية الحياة', 'Executive guide by Al-Hayat Pharmacy covering 24/7 Prescription Verification & Delivery benchmarks in Bahrain.', 'دليل تنفيذي من صيدلية الحياة حول معايير صرف الوصفات الطبية والتوصيل على مدار الساعة في البحرين.', 'Operations', '{"pharmacy","operations","Sanabis","2026"}'::text[], 'Bader Ali', 'published', now() - interval '12 days', true, now() - interval '12 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-2', 'Do all invoices include Bahrain NBR 10% VAT and Arabic breakdown?', 'هل تشمل الفواتير ضريبة القيمة المضافة 10% والتفصيل باللغتين؟', 'Yes. Every tax invoice is issued in BHD under CR CR-131770-1 and VAT ID 200013177000002 with itemized bilingual lines.', 'نعم، تصدر جميع الفواتير الضريبية بعملة BHD وفق السجل CR-131770-1 والرقم الضريبي 200013177000002.', 'billing', true, 2, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
